import json
import itertools

with open("/app/puzzles.json") as f:
    puzzles = json.load(f)

OPS = ["⊕", "⊗", "◇", "▽", "⊘", "⊛", "⊞", "⊠", "△"]

# Let's test individual operator variants one at a time vs our primary model,
# and also combinations of (⊞, ⊕, ⊠, ⊗, ⊘, ⊛, ◇, ▽, △).

def base_op(sym, a, b, n, i, d):
    if sym == "⊕": return a + b + i
    if sym == "⊗": return a * b - 1
    if sym == "◇": return max(a, b)
    if sym == "▽": return abs(a - b)
    if sym == "⊘": return 2 * a - b
    if sym == "⊛": return a + b ** 2
    if sym == "⊞": return a + b + d
    if sym == "⊠": return a + b + n
    if sym == "△": return max(0, a - b)

VARIANTS = {
    "⊕": {
        "a+b+i": lambda a, b, n, i, d: a + b + i,
        "a+b+1": lambda a, b, n, i, d: a + b + 1,
        "a+b+d+1": lambda a, b, n, i, d: a + b + d + 1,
        "a+b+n-1": lambda a, b, n, i, d: a + b + n - 1,
        "a+b+i+d": lambda a, b, n, i, d: a + b + i + d,
    },
    "⊗": {
        "a*b-1": lambda a, b, n, i, d: a * b - 1,
        "a*b-(d+1)": lambda a, b, n, i, d: a * b - (d + 1),
        "a*b+(d-1)": lambda a, b, n, i, d: a * b + d - 1,
    },
    "◇": {
        "max(a,b)": lambda a, b, n, i, d: max(a, b),
        "max(a,b)+d": lambda a, b, n, i, d: max(a, b) + d,
        "max(a,b)+i-1": lambda a, b, n, i, d: max(a, b) + i - 1,
        "max(a,b)+n-2": lambda a, b, n, i, d: max(a, b) + n - 2,
        "a_if_a_odd_else_b": lambda a, b, n, i, d: a if a % 2 == 1 else b,
        "a_if_a>b_else_b": lambda a, b, n, i, d: max(a, b),
    },
    "▽": {
        "abs(a-b)": lambda a, b, n, i, d: abs(a - b),
        "abs(a-b)+d": lambda a, b, n, i, d: abs(a - b) + d,
        "abs(a-b)+i-1": lambda a, b, n, i, d: abs(a - b) + i - 1,
        "abs(a-b)+n-2": lambda a, b, n, i, d: abs(a - b) + n - 2,
    },
    "⊘": {
        "2*a-b": lambda a, b, n, i, d: 2 * a - b,
        "n*a-b": lambda a, b, n, i, d: n * a - b,
        "(d+2)*a-b": lambda a, b, n, i, d: (d + 2) * a - b,
        "(i+1)*a-b": lambda a, b, n, i, d: (i + 1) * a - b,
        "2*a-b+d": lambda a, b, n, i, d: 2 * a - b + d,
        "2*a-b+n-2": lambda a, b, n, i, d: 2 * a - b + n - 2,
        "2*a-b+i-1": lambda a, b, n, i, d: 2 * a - b + i - 1,
    },
    "⊛": {
        "a+b**2": lambda a, b, n, i, d: a + b ** 2,
        "a+b**n": lambda a, b, n, i, d: a + (b ** n if abs(b) < 30 else 10**18),
        "a+b**(d+2)": lambda a, b, n, i, d: a + (b ** (d + 2) if abs(b) < 30 else 10**18),
        "a+b**(i+1)": lambda a, b, n, i, d: a + (b ** (i + 1) if abs(b) < 30 else 10**18),
        "a+b**2+d": lambda a, b, n, i, d: a + b ** 2 + d,
        "a+b**2+n-2": lambda a, b, n, i, d: a + b ** 2 + n - 2,
        "a+b**2+i-1": lambda a, b, n, i, d: a + b ** 2 + i - 1,
    },
    "⊞": {
        "a+b+d": lambda a, b, n, i, d: a + b + d,
        "a+b": lambda a, b, n, i, d: a + b,
        "a+b+i-1": lambda a, b, n, i, d: a + b + i - 1,
        "a+b+n-2": lambda a, b, n, i, d: a + b + n - 2,
    },
    "⊠": {
        "a+b+n": lambda a, b, n, i, d: a + b + n,
        "a+b+d+2": lambda a, b, n, i, d: a + b + d + 2,
        "a+b+n+d-1": lambda a, b, n, i, d: a + b + n + d - 1,
    },
    "△": {
        "max(0,a-b)": lambda a, b, n, i, d: max(0, a - b),
        "max(0,a-b)+d": lambda a, b, n, i, d: max(0, a - b) + d,
        "a-b_if_same_parity_else_0": lambda a, b, n, i, d: (a - b) if (a % 2 == b % 2) else 0,
    },
}

def eval_tree(nums, ops, shape, fn_map):
    a1, a2, a3, a4 = nums
    o1, o2, o3 = ops
    n = 4
    if shape == 0:
        v = fn_map[o1](a1, a2, n, 1, 2)
        v = fn_map[o2](v, a3, n, 2, 1)
        v = fn_map[o3](v, a4, n, 3, 0)
        expr = f"{a1} {o1} {a2} {o2} {a3} {o3} {a4}"
    elif shape == 1:
        v = fn_map[o2](a2, a3, n, 2, 2)
        v = fn_map[o1](a1, v, n, 1, 1)
        v = fn_map[o3](v, a4, n, 3, 0)
        expr = f"({a1} {o1} ({a2} {o2} {a3})) {o3} {a4}"
    elif shape == 2:
        v1 = fn_map[o1](a1, a2, n, 1, 1)
        v2 = fn_map[o3](a3, a4, n, 3, 1)
        v = fn_map[o2](v1, v2, n, 2, 0)
        expr = f"({a1} {o1} {a2}) {o2} ({a3} {o3} {a4})"
    elif shape == 3:
        v = fn_map[o2](a2, a3, n, 2, 2)
        v = fn_map[o3](v, a4, n, 3, 1)
        v = fn_map[o1](a1, v, n, 1, 0)
        expr = f"{a1} {o1} (({a2} {o2} {a3}) {o3} {a4})"
    elif shape == 4:
        v = fn_map[o3](a3, a4, n, 3, 2)
        v = fn_map[o2](a2, v, n, 2, 1)
        v = fn_map[o1](a1, v, n, 1, 0)
        expr = f"{a1} {o1} ({a2} {o2} ({a3} {o3} {a4}))"
    return v, expr

base_map = {sym: next(iter(VARIANTS[sym].values())) for sym in OPS}

print("Single-operator variant scan:")
for sym in OPS:
    for vname, vfn in VARIANTS[sym].items():
        fn_map = dict(base_map)
        fn_map[sym] = vfn
        solved = {}
        for pk, pv in puzzles.items():
            nums, target = pv["numbers"], pv["target"]
            cnt = 0
            ex = None
            for shape in range(5):
                for ops in itertools.product(OPS, repeat=3):
                    val, expr = eval_tree(nums, ops, shape, fn_map)
                    if val == target:
                        cnt += 1
                        if ex is None:
                            ex = expr
            solved[pk] = (cnt, ex)
        solved_keys = [pk for pk, (c, _) in solved.items() if c > 0]
        print(f"  {sym} = {vname:25s} -> {len(solved_keys)} solved: {solved_keys}")
        for pk in solved_keys:
            if pk in ["P1", "P4", "P6", "P7", "P8"]:
                print(f"      NEW SOL {pk}: {solved[pk][1]} (count={solved[pk][0]})")

import json
import itertools

with open("/app/puzzles.json") as f:
    puzzles = json.load(f)

OPS = ["⊕", "⊗", "◇", "▽", "⊘", "⊛", "⊞", "⊠", "△"]

# Precompute shapes and test combinations of (⊕, ⊞, ⊠, ⊗, ⊘, ⊛)
plus_circ_opts = {
    "a+b+1": lambda a, b, n, i, d: a + b + 1,
    "a+b+i": lambda a, b, n, i, d: a + b + i,
    "a+b+d+1": lambda a, b, n, i, d: a + b + d + 1,
    "a+b+n-1": lambda a, b, n, i, d: a + b + n - 1,
}
plus_box_opts = {
    "a+b": lambda a, b, n, i, d: a + b,
    "a+b+d": lambda a, b, n, i, d: a + b + d,
    "a+b+i-1": lambda a, b, n, i, d: a + b + i - 1,
    "a+b+n-2": lambda a, b, n, i, d: a + b + n - 2,
}
times_box_opts = {
    "a+b+n": lambda a, b, n, i, d: a + b + n,
    "a+b+d+2": lambda a, b, n, i, d: a + b + d + 2,
}
times_circ_opts = {
    "a*b-1": lambda a, b, n, i, d: a * b - 1,
    "a*b-d-1": lambda a, b, n, i, d: a * b - d - 1,
    "a*b+d-1": lambda a, b, n, i, d: a * b + d - 1,
}
slash_opts = {
    "2*a-b": lambda a, b, n, i, d: 2 * a - b,
    "n*a-b": lambda a, b, n, i, d: n * a - b,
    "(d+2)*a-b": lambda a, b, n, i, d: (d + 2) * a - b,
    "(i+1)*a-b": lambda a, b, n, i, d: (i + 1) * a - b,
    "2*a-b+d": lambda a, b, n, i, d: 2 * a - b + d,
}
star_opts = {
    "a+b**2": lambda a, b, n, i, d: a + b ** 2,
    "a+b**(d+2)": lambda a, b, n, i, d: a + (b ** (d + 2) if abs(b) < 20 else 10**18),
    "a+b**2+d": lambda a, b, n, i, d: a + b ** 2 + d,
}

def eval_tree(nums, ops, shape, fn_map):
    a1, a2, a3, a4 = nums
    o1, o2, o3 = ops
    n = 4
    if shape == 0:
        v = fn_map[o1](a1, a2, n, 1, 2)
        v = fn_map[o2](v, a3, n, 2, 1)
        v = fn_map[o3](v, a4, n, 3, 0)
    elif shape == 1:
        v = fn_map[o2](a2, a3, n, 2, 2)
        v = fn_map[o1](a1, v, n, 1, 1)
        v = fn_map[o3](v, a4, n, 3, 0)
    elif shape == 2:
        v1 = fn_map[o1](a1, a2, n, 1, 1)
        v2 = fn_map[o3](a3, a4, n, 3, 1)
        v = fn_map[o2](v1, v2, n, 2, 0)
    elif shape == 3:
        v = fn_map[o2](a2, a3, n, 2, 2)
        v = fn_map[o3](v, a4, n, 3, 1)
        v = fn_map[o1](a1, v, n, 1, 0)
    elif shape == 4:
        v = fn_map[o3](a3, a4, n, 3, 2)
        v = fn_map[o2](a2, v, n, 2, 1)
        v = fn_map[o1](a1, v, n, 1, 0)
    return v

best = []
# Let's first search over (plus_circ, plus_box, times_box, times_circ) keeping slash=2*a-b, star=a+b**2
fixed = {
    "◇": lambda a, b, n, i, d: max(a, b),
    "▽": lambda a, b, n, i, d: abs(a - b),
    "△": lambda a, b, n, i, d: max(0, a - b),
}

puz_list = [(pk, pv["numbers"], pv["target"]) for pk, pv in puzzles.items()]
all_trees = [(shape, ops) for shape in range(5) for ops in itertools.product(OPS, repeat=3)]

for k1, f1 in plus_circ_opts.items():
    for k2, f2 in plus_box_opts.items():
        for k3, f3 in times_box_opts.items():
            for k4, f4 in times_circ_opts.items():
                for k5, f5 in [("2*a-b", slash_opts["2*a-b"]), ("n*a-b", slash_opts["n*a-b"])]:
                    for k6, f6 in [("a+b**2", star_opts["a+b**2"])]:
                        fn_map = dict(fixed)
                        fn_map["⊕"] = f1
                        fn_map["⊞"] = f2
                        fn_map["⊠"] = f3
                        fn_map["⊗"] = f4
                        fn_map["⊘"] = f5
                        fn_map["⊛"] = f6
                        solved = []
                        for pk, nums, target in puz_list:
                            for shape, ops in all_trees:
                                if eval_tree(nums, ops, shape, fn_map) == target:
                                    solved.append(pk)
                                    break
                        if len(solved) >= 5:
                            print(f"{len(solved)} solved {solved}: ⊕={k1}, ⊞={k2}, ⊠={k3}, ⊗={k4}, ⊘={k5}")

import json
import itertools

with open("/app/puzzles.json") as f:
    puzzles = json.load(f)

OPS = ["⊕", "⊗", "◇", "▽", "⊘", "⊛", "⊞", "⊠", "△"]

def make_model(plus_circ_is_i=True, plus_box_is_d=True):
    def eval_op(sym, a, b, n, i, d):
        if sym == "⊕": return a + b + (i if plus_circ_is_i else 1)
        if sym == "⊗": return a * b - 1
        if sym == "◇": return max(a, b)
        if sym == "▽": return abs(a - b)
        if sym == "⊘": return 2 * a - b
        if sym == "⊛": return a + b ** 2
        if sym == "⊞": return a + b + (d if plus_box_is_d else 0)
        if sym == "⊠": return a + b + n
        if sym == "△": return max(0, a - b)
    return eval_op

def eval_tree(nums, ops, shape, fn):
    a1, a2, a3, a4 = nums
    o1, o2, o3 = ops
    n = 4
    if shape == 0:
        v = fn(o1, a1, a2, n, 1, 2)
        v = fn(o2, v, a3, n, 2, 1)
        v = fn(o3, v, a4, n, 3, 0)
        expr = f"{a1} {o1} {a2} {o2} {a3} {o3} {a4}"
    elif shape == 1:
        v = fn(o2, a2, a3, n, 2, 2)
        v = fn(o1, a1, v, n, 1, 1)
        v = fn(o3, v, a4, n, 3, 0)
        expr = f"({a1} {o1} ({a2} {o2} {a3})) {o3} {a4}"
    elif shape == 2:
        v1 = fn(o1, a1, a2, n, 1, 1)
        v2 = fn(o3, a3, a4, n, 3, 1)
        v = fn(o2, v1, v2, n, 2, 0)
        expr = f"({a1} {o1} {a2}) {o2} ({a3} {o3} {a4})"
    elif shape == 3:
        v = fn(o2, a2, a3, n, 2, 2)
        v = fn(o3, v, a4, n, 3, 1)
        v = fn(o1, a1, v, n, 1, 0)
        expr = f"{a1} {o1} (({a2} {o2} {a3}) {o3} {a4})"
    elif shape == 4:
        v = fn(o3, a3, a4, n, 3, 2)
        v = fn(o2, a2, v, n, 2, 1)
        v = fn(o1, a1, v, n, 1, 0)
        expr = f"{a1} {o1} ({a2} {o2} ({a3} {o3} {a4}))"
    return v, expr

for name, pci, pbd in [("Model1(i,d,n)", True, True), ("Model2(1,d,n)", False, True)]:
    print(f"\n=== {name} ===")
    fn = make_model(pci, pbd)
    for pk, pv in puzzles.items():
        nums, target = pv["numbers"], pv["target"]
        vals = {}
        for shape in range(5):
            for ops in itertools.product(OPS, repeat=3):
                v, expr = eval_tree(nums, ops, shape, fn)
                vals.setdefault(v, []).append(expr)
        near = sorted(vals.keys(), key=lambda x: abs(x - target))[:5]
        print(f"{pk} {nums} = {target}: exact={len(vals.get(target, []))}, nearest={[(x, vals[x][0]) for x in near[:3]]}")

import json
import itertools

with open("/app/puzzles.json") as f:
    puzzles = json.load(f)

OPS = ["⊕", "⊗", "◇", "▽", "⊘", "⊛", "⊞", "⊠", "△"]

def eval_tree(nums, ops, shape, plus_circ_fn):
    a1, a2, a3, a4 = nums
    o1, o2, o3 = ops
    n = 4
    def fn(sym, a, b, n, i, d):
        if sym == "⊕": return plus_circ_fn(a, b, n, i, d)
        if sym == "⊗": return a * b - 1
        if sym == "◇": return max(a, b)
        if sym == "▽": return abs(a - b)
        if sym == "⊘": return 2 * a - b
        if sym == "⊛": return a + b ** 2
        if sym == "⊞": return a + b + d
        if sym == "⊠": return a + b + n
        if sym == "△": return max(0, a - b)

    if shape == 0:
        v = fn(o1, a1, a2, n, 1, 2); v = fn(o2, v, a3, n, 2, 1); v = fn(o3, v, a4, n, 3, 0)
    elif shape == 1:
        v = fn(o2, a2, a3, n, 2, 2); v = fn(o1, a1, v, n, 1, 1); v = fn(o3, v, a4, n, 3, 0)
    elif shape == 2:
        v1 = fn(o1, a1, a2, n, 1, 1); v2 = fn(o3, a3, a4, n, 3, 1); v = fn(o2, v1, v2, n, 2, 0)
    elif shape == 3:
        v = fn(o2, a2, a3, n, 2, 2); v = fn(o3, v, a4, n, 3, 1); v = fn(o1, a1, v, n, 1, 0)
    elif shape == 4:
        v = fn(o3, a3, a4, n, 3, 2); v = fn(o2, a2, v, n, 2, 1); v = fn(o1, a1, v, n, 1, 0)
    return v

all_trees = [(shape, ops) for shape in range(5) for ops in itertools.product(OPS, repeat=3)]

for label, fn in [
    ("a+b+1", lambda a,b,n,i,d: a+b+1),
    ("a+b+i", lambda a,b,n,i,d: a+b+i),
    ("a+b+2", lambda a,b,n,i,d: a+b+2),
    ("a+b+3", lambda a,b,n,i,d: a+b+3),
    ("a+b+4", lambda a,b,n,i,d: a+b+4),
    ("a+b-1", lambda a,b,n,i,d: a+b-1),
    ("a+b-2", lambda a,b,n,i,d: a+b-2),
    ("a+b+5", lambda a,b,n,i,d: a+b+5),
    ("a+b+2*i", lambda a,b,n,i,d: a+b+2*i),
    ("a+b+2*d", lambda a,b,n,i,d: a+b+2*d),
]:
    solved = []
    for pk, pv in puzzles.items():
        for shape, ops in all_trees:
            if eval_tree(pv["numbers"], ops, shape, fn) == pv["target"]:
                solved.append(pk)
                break
    print(f"{label:10s}: {len(solved)} solved -> {solved}")

